package com.donotmiss.backend.aiapplication.career.gap;
import com.donotmiss.backend.aiapplication.career.gap.evaluation.GapAnalysisEvaluation; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.assertThat;
class GapAnalysisEvaluationTest {@Test void reportsStatusAndClassMetrics(){var metrics=GapAnalysisEvaluation.evaluate(List.of(new GapAnalysisEvaluation.Case("a",GapStatus.MATCH),new GapAnalysisEvaluation.Case("b",GapStatus.GAP),new GapAnalysisEvaluation.Case("c",GapStatus.UNKNOWN)),Map.of("a",GapStatus.MATCH,"b",GapStatus.GAP,"c",GapStatus.UNKNOWN));assertThat(metrics.statusAccuracy()).isEqualTo(1);assertThat(metrics.byStatus().get(GapStatus.MATCH).precision()).isEqualTo(1);assertThat(metrics.byStatus().get(GapStatus.UNKNOWN).recall()).isEqualTo(1);}}
